11	// `contacts` honours { id, name, email, role, clientId }.
12	import { test, expect, type Page, type Locator } from '@playwright/test';
13	import { resetAndSeed } from '../support/seed';
14	
15	const contactRows = (page: Page) => page.locator('[data-testid^="contact-row-"]');
16	
