1	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
2	import { getJson, postJson } from '../../api/http';
3	
4	// The shape the server returns and the query key everything that shows clients shares. Two features
5	// stay in step by invalidating ['clients']; nothing imports a sibling to refresh it.
6	export type Client = { id: number; name: string; email: string; archived: boolean };
7	
8	export const clientsKey = ['clients'] as const;
9	
10	export function useClients() {
11	  return useQuery({
12	    queryKey: clientsKey,
13	    queryFn: () => getJson<Client[]>('/api/clients'),
14	  });
15	}
16	
17	export function useCreateClient() {
18	  const queryClient = useQueryClient();
19	  return useMutation({
20	    mutationFn: (input: { name: string; email: string }) =>
21	      postJson<Client>('/api/clients', input),
22	    onSuccess: () => queryClient.invalidateQueries({ queryKey: clientsKey }),
23	  });
24	}
25	
26	// Archive a client instead of deleting it: POSTs {id} and returns the id archived. The client is
27	// kept server-side with its archived flag set; invalidating ['clients'] re-reads every view so the
28	// row drops off the list and search with no hand-maintained list (CLAUDE.md rule 5). The audit
29	// record is written server-side.
30	export function useArchiveClient() {
